# Code generated by Claude
"""Offscreen copy of the live viewer's picture, for the replay tool's `--video viewer` mode.

CompositeRenderer draws one frame per call from a simulation state, without a window:

    comp = CompositeRenderer(model, context, camera_specs, size=(1920, 1080), legend_extra=[...])
    rgb = comp.render(data, info)          # (H, W, 3) uint8, row 0 on top

The layout is the live viewer's (src/glfw_viewer.py), scaled by the frame height divided by 960 (the live viewer
window is 1280 by 960 pixels). The follow camera fills the frame (3.5 m behind and 45 degrees above the robot base,
turning with it, 90 degree vertical field of view (FOV)). The status panel is at the top left, with the same rows and
key legend. The simulated cameras (eagle and both wrists) are in a row of tiles along the bottom, each with its name in
the corner.

Differences from the live viewer, all deliberate and made for a video: shadows are on in the follow view and in
all the cameras; the tiles come from full-size (640 by 480 pixel) renders of the policy cameras, updated every frame
(the live insets are 320 by 240 pixels, have shadows off and update once per second per camera); and the rows that only
mean something live are replaced or left out (the viewer frame time becomes the video frame time, the F6 recording state
and the keyboard's own normalised command are left out, and a "twist lin, ang" row shows the applied base command). The
"episode", "controller" and neck rows are filled from the `info` dictionary that render() takes.
"""

import math

import cv2
import mujoco
import numpy as np

from src import robot_specs
from src.cameras import CameraRig
from src.glfw_viewer import CAM_DISTANCE, CAM_ELEVATION, FOVY_DEG, hud_key_list, text_bitmap
from src.neck import neck_ids

REFERENCE_HEIGHT = 960          # the live viewer window is 1280x960


class CompositeRenderer:
    """Renders the live viewer's layout offscreen, one red-green-blue (RGB) frame per render() call.

    Attributes:
        model (mujoco.MjModel): The robot model.
        context (mujoco.MjrContext): Rendering context shared with the camera
            rig. It must be an offscreen-capable context (the replay tool
            creates one without a window).
        W (int): Frame width in pixels.
        H (int): Frame height in pixels.
        s (float): Scale factor, H / REFERENCE_HEIGHT, applied to the panel
            and the camera tiles.
        opt (mujoco.MjvOption): Visualisation options for the follow view.
        cam (mujoco.MjvCamera): The free follow camera (distance
            CAM_DISTANCE, elevation CAM_ELEVATION), moved each frame.
        scene (mujoco.MjvScene): Scene buffer for the follow view, with shadows
            and reflections on.
        rig (src.cameras.CameraRig): Renders the simulated cameras, all with
            shadows on. The tiles are its images.
        base_body (int): Id of the body "base_link" that the follow camera
            tracks (1 if the model has no such body).
        neck (dict | None): Neck joint ids from src.neck.neck_ids, or None if
            the model has no neck. Used for the neck row of the panel.
        keys (list[tuple[str, str]]): Key legend entries of the panel (without
            the F2 entry).
    """

    def __init__(self, model, context, camera_specs, size=(1920, 1080), legend_extra=()):
        """Set up the follow camera, the scene and the camera rig.

        Sets model.vis.global_.fovy to FOVY_DEG (90 degrees), as the live
        viewer does.

        Args:
            model (mujoco.MjModel): The robot model.
            context (mujoco.MjrContext): Rendering context to render with. Its
                offscreen buffer must be at least `size` large.
            camera_specs (list[dict]): Camera definitions as in
                robot_specs.CAMERA_SPECS (name, resolution and so on). Each is
                copied with "shadows" set to True.
            size (tuple[int, int]): Frame (width, height) in pixels. Defaults
                to (1920, 1080).
            legend_extra (Sequence[tuple[str, str]]): Extra (key, label)
                entries for the key legend, for example ("F9", "take over").
                Defaults to an empty tuple.
        """
        self.model, self.context = model, context
        self.W, self.H = size
        self.s = self.H / REFERENCE_HEIGHT
        model.vis.global_.fovy = FOVY_DEG                              # as the viewer sets it (the follow camera is a free camera)
        self.opt = mujoco.MjvOption()
        self.cam = mujoco.MjvCamera()
        mujoco.mjv_defaultCamera(self.cam)
        mujoco.mjv_defaultOption(self.opt)
        self.cam.distance, self.cam.elevation, self.cam.azimuth = CAM_DISTANCE, CAM_ELEVATION, 90
        self.scene = mujoco.MjvScene(model, maxgeom=10_000)
        self.scene.flags[mujoco.mjtRndFlag.mjRND_SHADOW] = 1
        self.scene.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = 1
        self.rig = CameraRig(model, [{**cs, "shadows": True} for cs in camera_specs], context, shadows=True)
        self.base_body = max(mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "base_link"), 1)
        self.neck = neck_ids(model, robot_specs.NECK_SPECS)
        self.keys = hud_key_list(False, legend_extra)

    def render(self, data, info):
        """Render one frame: follow view, status panel and camera tiles.

        Renders every camera of the rig, points the follow camera at the base
        (turning with the base yaw), renders the follow view offscreen, then
        draws the status panel at the top left and the camera tiles along the
        bottom edge.

        Args:
            data (mujoco.MjData): Simulation state to draw.
            info (dict): What the panel shows. Keys:
                "time" (float): Simulated time in seconds.
                "base_vel" (tuple[float, float, float]): Base velocity (vx, vy)
                  in metres per second and yaw rate in radians per second, in
                  the world frame.
                "twist" (tuple[float, float]): Applied base command, forward
                  speed in metres per second and yaw rate in radians per
                  second.
                "status" (str | None): Episode status text, or None for no row.
                "mode" (str | None): "auto" or "teleop", or None for no row.
                  Shown in upper case.
                "fps" (float): Video frame rate, in frames per second, for the
                  video row of the panel.

        Returns:
            numpy.ndarray: Frame of shape (H, W, 3), dtype uint8, in
            red-green-blue (RGB) order, row 0 at the top.
        """
        S = lambda v: int(round(v * self.s))
        model, W, H = self.model, self.W, self.H
        # --- the three cameras, then the follow view ---
        self.rig.render(data)
        qw, qx, qy, qz = data.xquat[self.base_body]
        yaw_deg = math.degrees(math.atan2(2.0 * (qw * qz + qx * qy), 1.0 - 2.0 * (qy * qy + qz * qz)))
        self.cam.lookat[:] = data.xpos[self.base_body]
        self.cam.azimuth = yaw_deg + 90
        mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_OFFSCREEN, self.context)
        viewport = mujoco.MjrRect(0, 0, W, H)
        mujoco.mjv_updateScene(model, data, self.opt, None, self.cam, mujoco.mjtCatBit.mjCAT_ALL, self.scene)
        mujoco.mjr_render(viewport, self.scene, self.context)
        rgb = np.zeros((H, W, 3), dtype=np.uint8)
        mujoco.mjr_readPixels(rgb, None, viewport, self.context)
        mujoco.mjr_setBuffer(mujoco.mjtFramebuffer.mjFB_WINDOW, self.context)
        frame = np.ascontiguousarray(np.flipud(rgb))

        # --- the status panel, top left ---
        vx, vy, wz = info["base_vel"]
        lin, ang = info["twist"]
        rows = [("sim time", f"{info['time']:.2f} s"),
                ("base speed (m/s)", f"{math.hypot(vx, vy):.2f}"),
                ("base vx, vy (m/s)", f"{vx:+.2f}, {vy:+.2f}"),
                ("yaw rate (rad/s)", f"{wz:+.2f}"),
                ("yaw (deg)", f"{yaw_deg:+.1f}"),
                ("position x, y, z (m)", f"{data.qpos[0]:.2f}, {data.qpos[1]:.2f}, {data.qpos[2]:.3f}"),
                ("video (ms, fps)", f"{1000.0 / info['fps']:.0f}, {info['fps']:.1f}"),
                ("twist lin, ang", f"{lin:+.2f}, {ang:+.2f}")]
        if info.get("status"):
            rows.append(("episode", info["status"]))
        if info.get("mode"):
            rows.append(("controller", info["mode"].upper()))
        if self.neck is not None:
            rows.append(("neck pan,lift,elb,wrist", ", ".join(f"{math.degrees(float(data.qpos[a])):+.0f}" for a in self.neck["qadr"])))
        hud = text_bitmap(rows, S(400), S(180), self.keys, self.s)
        m = S(8)
        frame[m:m + hud.shape[0], m:m + hud.shape[1]] = hud

        # --- the camera tiles, along the bottom ---
        tiles = list(self.rig.images.items())
        gap = S(8)
        iw = min(S(320), (W - gap * (len(tiles) + 1)) // len(tiles))
        ih = iw * 3 // 4
        x = gap
        for name, img in tiles:
            small = cv2.resize(img, (iw, ih), interpolation=cv2.INTER_AREA)
            cv2.rectangle(small, (0, 0), (S(len(name) * 9 + 10), S(20)), (45, 45, 45), -1)
            cv2.putText(small, name, (S(5), S(15)), cv2.FONT_HERSHEY_SIMPLEX, 0.5 * self.s, (255, 255, 255), max(1, int(round(self.s))), cv2.LINE_AA)
            frame[H - gap - ih:H - gap, x:x + iw] = small
            x += iw + gap
        return frame
